alter table public.gst_returns add constraint gst_returns_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'reviewed'::text, 'finalised'::text])));
alter table public.bank_transactions add constraint bank_transactions_amount_check CHECK ((amount <> (0)::numeric));
alter table public.bank_transactions add constraint bank_transactions_duplicate_status_check CHECK ((duplicate_status = ANY (ARRAY['new'::text, 'possible_duplicate'::text, 'already_imported'::text])));
alter table public.bank_transactions add constraint bank_transactions_reconciliation_type_v6212_ck CHECK (((reconciliation_type IS NULL) OR (reconciliation_type = ANY (ARRAY['invoice'::text, 'expense'::text, 'created_expense'::text, 'split'::text, 'group'::text, 'transfer'::text, 'excluded'::text, 'customer_refund'::text, 'supplier_refund'::text, 'payroll_pay_run'::text, 'owner_funds_introduced'::text, 'director_loan_received'::text, 'capital_contribution'::text, 'owner_drawings'::text, 'repay_owner_loan'::text, 'director_payment'::text, 'dividend_distribution'::text, 'expense_deposit_refund'::text]))));
alter table public.bank_transactions add constraint bank_transactions_status_check CHECK ((status = ANY (ARRAY['unreconciled'::text, 'reconciled'::text, 'excluded'::text])));
alter table public.bank_reconciliation_allocations add constraint bank_reconciliation_allocations_allocation_type_v6212_ck CHECK ((allocation_type = ANY (ARRAY['invoice'::text, 'expense'::text, 'transfer'::text, 'exclude'::text, 'customer_refund'::text, 'supplier_refund'::text, 'payroll_pay_run'::text, 'payroll_ird'::text, 'owner_equity'::text, 'expense_deposit_refund'::text, 'stripe_payout'::text])));
alter table public.bank_reconciliation_allocations add constraint bank_reconciliation_allocations_amount_check CHECK ((amount > (0)::numeric));
alter table public.accounting_journals add constraint accounting_journals_journal_type_c45 CHECK ((journal_type = ANY (ARRAY['invoice'::text, 'customer_payment'::text, 'expense'::text, 'supplier_payment'::text, 'payroll'::text, 'bank'::text, 'credit_note'::text, 'supplier_credit'::text, 'customer_refund'::text, 'supplier_refund'::text, 'depreciation'::text, 'manual'::text, 'opening_balance'::text, 'year_end'::text, 'tax_adjustment'::text])));
alter table public.accounting_journals add constraint accounting_journals_posting_version_check CHECK ((posting_version > 0));
alter table public.accounting_journals add constraint accounting_journals_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'posted'::text, 'reversed'::text])));
